254	    private LoadResponse doLoad(String legId, LoadRequest request) {
255	        LegRow leg = lockLeg(legId);
256	        checkVersion(leg, request.expectedVersion());
257	        if (!LEG_OPEN.equals(leg.status())) {
258	            throw ApiException.unprocessable("航段状态为 " + leg.status() + "，禁止装载");
259	        }
260	        List<String> bagTags = request.bagTags();
261	        if (new HashSet<>(bagTags).size() != bagTags.size()) {
262	            throw ApiException.unprocessable("批量装载的 bagTag 不得重复");
263	        }
264	        List<String> sorted = sortedCopy(bagTags);
265	        List<BagRow> bags = new ArrayList<>();
266	        for (String bagTag : sorted) {
267	            BagRow bag = lockBag(bagTag);
268	            if (bag == null) {
269	                throw ApiException.unprocessable("行李不存在: " + bagTag);
270	            }
271	            validateLoadable(bag, leg);
272	            bags.add(bag);
273	        }
274	        for (BagRow bag : bags) {
275	            jdbcTemplate.update("INSERT INTO load_record (bag_tag, leg_id) VALUES (?, ?)", bag.bagTag(), legId);
276	            jdbcTemplate.update("UPDATE bag SET loaded_leg_id = ? WHERE bag_tag = ?", legId, bag.bagTag());
277	            insertEvent(bag.bagTag(), EVT_LOADED, legId, leg.origin());
278	        }
279	        int newVersion = leg.version() + 1;
280	        jdbcTemplate.update("UPDATE leg SET version = ? WHERE leg_id = ?", newVersion, legId);
281	        return new LoadResponse(legId, LEG_OPEN, newVersion, sorted);
282	    }
