17	 */
18	@RestControllerAdvice
19	public class GlobalExceptionHandler {
20	
21	    @ExceptionHandler(ApiException.class)
22	    public ResponseEntity<Map<String, Object>> handleApi(ApiException ex) {
23	        return build(ex.getStatus(), ex.getMessage());
24	    }
25	
26	    @ExceptionHandler(MethodArgumentNotValidException.class)
27	    public ResponseEntity<Map<String, Object>> handleValidation(MethodArgumentNotValidException ex) {
28	        String message = ex.getBindingResult().getFieldErrors().stream()
29	                .findFirst()
30	                .map(FieldError::getDefaultMessage)
31	                .orElse("请求参数不合法");
32	        return build(HttpStatus.BAD_REQUEST, message);
33	    }
